def splitStringDescending(s: str) -> bool:
    def dfs(idx, prev):
        if idx == len(s): return True
        for j in range(idx + 1, len(s) + 1):
            val = int(s[idx:j])
            if val == prev - 1:
                if dfs(j, val): return True
        return False
    for i in range(1, len(s)):
        val = int(s[:i])
        if dfs(i, val): return True
    return False

